; Fade out and stop all sound
; $9336-$9347

; Waits for the end of a fade-in, then fades out. Then it silences the SID and clears the sound state.
stop_sound
        lda fade_in_request
        bmi stop_sound
        lda #$81                        ; Requests a fade-out.
        sta fade_out_request
stop_sound_wait_fade_out
        lda fade_out_request            ; The timer IRQ clears bit 7 when the volume is 0.
        bmi stop_sound_wait_fade_out
        sei
        jsr init_sound                  ; Clears the SID registers, the sound variables and their shadows.
        cli
        rts
